const request = $('Webhook autenticado de consulta').first().json.body;
if (!request?.queryId || !request?.question || !request?.embeddingModel || !request?.ollamaBaseUrl || !request?.qdrantCollection || !request?.qdrantUrl || !request?.callbackUrl || !Number.isFinite(request?.minSimilarity)) throw new Error('Payload de consulta incompleto');
return [{ json: { model: request.embeddingModel, input: request.question, ollamaBaseUrl: request.ollamaBaseUrl } }];

const request = $('Webhook autenticado de consulta').first().json.body;
const result = $input.first().json;
const vector = (result.embeddings ?? result.body?.embeddings)?.[0];
if (!Array.isArray(vector) || vector.length < 1 || vector.some(n => !Number.isFinite(n))) throw new Error('Embedding de consulta inválido');
return [{ json: { vector, collection: request.qdrantCollection, qdrantUrl: request.qdrantUrl.replace(/\/$/, '') } }];

const request = $('Webhook autenticado de consulta').first().json.body;
const courses = $('Leer catálogo activo PostgreSQL').first().json.data?.items;
const response = $input.first().json;
const hits = response.result?.points ?? response.body?.result?.points;
if (!Array.isArray(courses) || !Array.isArray(hits)) throw new Error('Respuesta de catálogo o Qdrant inválida');
const active = new Map(courses.map(c => [c.id, c]));
const seen = new Set();
const sources = hits.map(hit => { const courseId = hit.payload?.course_id; const course = active.get(courseId); if (!course || seen.has(courseId) || !Number.isFinite(hit.score) || hit.score < request.minSimilarity) return null; seen.add(courseId); return { courseId, similarity: hit.score, name: course.name, description: course.description, category: course.category, level: course.level, intecapCareerType: course.intecapCareerType ?? null, durationHours: course.durationHours }; }).filter(Boolean).sort((a,b) => b.similarity-a.similarity).slice(0,5);
if (sources.length < 3) return [{ json: { queryId: request.queryId, status: 'Sin resultados' } }];
return [{ json: { queryId: request.queryId, question: request.question, experienceLevel: request.experienceLevel, interestArea: request.interestArea, chatModel: request.chatModel, status: 'Respondida', sources, context: sources.map((s,i) => `${i+1}. ${s.name} | ${s.category} | Nivel RutaIA: ${s.level} | Clasificación INTECAP: ${s.intecapCareerType ?? 'No indicada'} | ${s.durationHours} horas | score ${s.similarity}\n${s.description}`).join('\n\n') } }];

const original = $('Webhook autenticado de consulta').first().json.body;
const selected = $('Filtrar fuentes activas y umbral').first().json;
const response = $input.first().json;
let content = response.message?.content ?? response.body?.message?.content;
if (typeof content !== 'string') throw new Error('Ollama no devolvió texto');
const parsed = JSON.parse(content);
for (const key of ['answer','summary','explanation']) if (typeof parsed[key] !== 'string' || !parsed[key].trim()) throw new Error('Respuesta RAG incompleta');
return [{ json: { queryId: original.queryId, status: 'Respondida', answer: parsed.answer, summary: parsed.summary, explanation: parsed.explanation, sources: selected.sources.map(s => ({ courseId: s.courseId, similarity: s.similarity })) } }];
